async function renderSearch(query){
  const term=String(query??"").trim(),request=++searchRequest;
  if(!term){currentSearchHits=new Map();renderSearchStatus(searchStatus(term,"idle"));return;}
  renderSearchStatus(searchStatus(term,"loading"));
  try{
    const raw=adapter.kind==="tauri"?await adapter.search(term,50):buildBrowserSearchHits(workspace(),term,50);
    if(request!==searchRequest)return;
    const hits=normalizeSearchHits(raw??[],50);currentSearchHits=new Map(hits.map(hit=>[hit.entityId,hit]));
    if(!hits.length){renderSearchStatus(searchStatus(term,"empty"));return;}
    const results=$("#searchResults");results.replaceChildren();
    for(const hit of hits){const button=document.createElement("button"),icon=document.createElement("span"),copy=document.createElement("span"),title=document.createElement("strong"),snippet=document.createElement("small");button.type="button";button.dataset.searchEntityId=hit.entityId;icon.className="result-icon";icon.setAttribute("aria-hidden","true");icon.textContent=hit.entityType==="row"?"▦":"□";title.textContent=hit.title;snippet.textContent=hit.snippet;copy.append(title,snippet);button.append(icon,copy);results.append(button);}
  }catch{if(request===searchRequest){currentSearchHits=new Map();renderSearchStatus(searchStatus(term,"error"));}}
}
function renderSearchStatus(status){const results=$("#searchResults"),message=document.createElement("div");message.className=`search-hint search-${status.kind}`;message.textContent=status.message;results.replaceChildren(message);if(status.kind==="error"){const retry=document.createElement("button");retry.type="button";retry.dataset.searchRetry="";retry.textContent="Retry search";results.append(retry);}}
